# qx2_jaccard :: ('hello', 'world')
def qx2_jaccard(a, b):
    sa, sb = set(a), set(b)
    if not sa and not sb:
        return 1.0
    return len(sa & sb) / len(sa | sb)

if __name__ == '__main__':
    print(qx2_jaccard(('hello', 'world')))

